package net.enchadd.mod; import net.enchadd.mod.common.ImmolateBehavior; import net.neoforged.neoforge.common.NeoForge; import net.neoforged.neoforge.event.entity.living.LivingIncomingDamageEvent; final class EnchADDNeoForgeImmolate{static void register(){NeoForge.EVENT_BUS.addListener(LivingIncomingDamageEvent.class,EnchADDNeoForgeImmolate::onDamage);}private static void onDamage(LivingIncomingDamageEvent e){ImmolateBehavior.onHit(e.getEntity(),e.getSource(),e.getAmount());}}
